function sndx(w){w=w.toLowerCase().replace(/[^a-z]/g,'');if(!w)return'';const c={b:1,f:1,p:1,v:1,c:2,g:2,j:2,k:2,q:2,s:2,x:2,z:2,d:3,t:3,l:4,m:5,n:5,r:6};let o=w[0],last=c[w[0]]||0;for(const ch of w.slice(1)){const k=c[ch]||0;if(k&&k!==last)o+=k;last=k;}return(o+'000').slice(0,4);}
